from typing import Protocol


class Printable(Protocol):
    def to_string(self) -> str: ...


class Comparable(Protocol):
    def __lt__(self, other) -> bool: ...


class Document:
    def __init__(self, title, body):
        self.title = title
        self.body = body

    def to_string(self):
        return f"{self.title}: {self.body}"


class Report:
    def __init__(self, title, data):
        self.title = title
        self.data = data

    def to_string(self):
        return f"Report: {self.title} ({len(self.data)} items)"


def print_all(items):
    return "\n".join(item.to_string() for item in items)


def find_min(items):
    result = items[0]
    for item in items[1:]:
        if item < result:
            result = item
    return result
